import{_ as t,o as h,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const e=JSON.parse('{"title":"Bảng Tóm tắt Biên niên sử","description":"","frontmatter":{},"headers":[],"relativePath":"vi/93-编年史简表.md","filePath":"vi/93-编年史简表.md","lastUpdated":1789183869000}'),g={name:"vi/93-编年史简表.md"};function a(d,n,u,o,r,m){return h(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="bang-tom-tat-bien-nien-su" tabindex="-1">Bảng Tóm tắt Biên niên sử <a class="header-anchor" href="#bang-tom-tat-bien-nien-su" aria-label="Permalink to &quot;Bảng Tóm tắt Biên niên sử&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>93</td></tr><tr><td>Mô-đun</td><td>Phụ lục và Tài liệu Tham khảo</td></tr><tr><td>Từ khóa chính</td><td>biên niên sử, phân chia kỷ nguyên, sự kiện quan trọng, nút lịch sử, Hengyuanzhou</td></tr></tbody></table><h2 id="_1-mo-ta-bien-nien-su" tabindex="-1">1. Mô tả Biên niên sử <a class="header-anchor" href="#_1-mo-ta-bien-nien-su" aria-label="Permalink to &quot;1. Mô tả Biên niên sử&quot;">​</a></h2><p>Bảng tóm tắt này dựa trên thời gian chuẩn của Hengyuanzhou, ghi lại theo thứ tự kỷ nguyên các sự kiện lịch sử quan trọng và các nút then chốt trong quá trình phát triển của Văn minh Cộng sinh Mỏ neo. Khoảng thời gian kéo dài từ thời kỳ cổ xưa của thời đại tiền-mỏ neo đến triển vọng tương lai của thời đại cộng sinh liên sao. Mỗi kỷ nguyên liệt kê thời gian bắt đầu và kết thúc, đặc điểm của thời đại, và các sự kiện quan trọng. Bảng tóm tắt này là một chỉ mục lịch sử được cô đặc hóa cao độ; đối với lịch sử chi tiết của mỗi kỷ nguyên, vui lòng xem các bài viết đặc biệt của tài liệu 70-79.</p><h2 id="_2-tong-quan-phan-chia-ky-nguyen" tabindex="-1">2. Tổng quan Phân chia Kỷ nguyên <a class="header-anchor" href="#_2-tong-quan-phan-chia-ky-nguyen" aria-label="Permalink to &quot;2. Tổng quan Phân chia Kỷ nguyên&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Số kỷ nguyên</th><th>Tên kỷ nguyên</th><th>Thời gian bắt đầu và kết thúc (năm chuẩn Hengyuanzhou)</th><th>Thời lượng</th><th>Đặc điểm cốt lõi</th></tr></thead><tbody><tr><td>Kỷ nguyên thứ nhất</td><td>Thời đại tiền-mỏ neo</td><td>Khoảng -10 tỷ đến -10.000 năm</td><td>Khoảng 10 tỷ năm</td><td>Hệ thống tu luyện kiểu cướp bóc chiếm ưu thế, chu kỳ trỗi dậy và sụp đổ của văn minh</td></tr><tr><td>Kỷ nguyên thứ hai</td><td>Kỷ nguyên thức tỉnh mỏ neo</td><td>-10.000 đến -1.000 năm</td><td>Khoảng 9.000 năm</td><td>Cơ chế mỏ neo được phát hiện và áp dụng ban đầu</td></tr><tr><td>Kỷ nguyên thứ ba</td><td>Giai đoạn thành lập hệ thống cộng sinh</td><td>-1.000 đến -100 năm</td><td>Khoảng 900 năm</td><td>Khung thể chế của Văn minh Cộng sinh Mỏ neo dần dần được thành lập</td></tr><tr><td>Kỷ nguyên thứ tư</td><td>Giai đoạn mở cửa hệ thống ba trăm bộ</td><td>-100 đến -50 năm</td><td>Khoảng 50 năm</td><td>Hệ thống tu luyện nguồn gốc ba trăm bộ được mở cửa hoàn toàn</td></tr><tr><td>Kỷ nguyên thứ năm</td><td>Giai đoạn chiến lược kích hoạt 20%</td><td>-50 năm đến năm gốc</td><td>Khoảng 50 năm</td><td>20% chúng sinh được kích hoạt trở thành người mạnh nhất cấp mặt phẳng</td></tr><tr><td>Kỷ nguyên thứ sáu</td><td>Kỷ nguyên nâng chiều không gian đầu tiên</td><td>Năm gốc đến 100 năm</td><td>100 năm</td><td>Văn minh cộng sinh lần đầu tiên đạt được nâng chiều không gian theo giai đoạn</td></tr><tr><td>Kỷ nguyên thứ bảy</td><td>Kỷ nguyên cộng hòa tất cả các chủng tộc</td><td>100 đến 500 năm</td><td>400 năm</td><td>Cộng hòa tất cả các chủng tộc chính thức thành lập, sự hòa nhập liên chủng tộc được sâu hóa</td></tr><tr><td>Kỷ nguyên thứ tám</td><td>Kỷ nguyên khám phá liên mặt phẳng</td><td>500 đến 2.000 năm</td><td>1.500 năm</td><td>Khám phá và hoạt động khảo cổ quy mô lớn liên mặt phẳng được triển khai</td></tr><tr><td>Kỷ nguyên thứ chín</td><td>Thời đại cộng sinh liên sao</td><td>2.000 năm đến tương lai</td><td>Đang diễn ra</td><td>Mạng lưới cộng sinh cấp vũ trụ được xây dựng, nâng chiều không gian tổng thể được tiến hành</td></tr></tbody></table><p>Ghi chú: &quot;Năm gốc&quot; đề cập đến năm mà Văn minh Cộng sinh Mỏ neo chính thức tuyên bố thành lập, được sử dụng làm điểm phân chia của niên biểu lịch sử.</p><h2 id="_3-thoi-đai-tien-mo-neo-khoang-10-ty-đen-10-000-nam" tabindex="-1">3. Thời đại tiền-mỏ neo (Khoảng -10 tỷ đến -10.000 năm) <a class="header-anchor" href="#_3-thoi-đai-tien-mo-neo-khoang-10-ty-đen-10-000-nam" aria-label="Permalink to &quot;3. Thời đại tiền-mỏ neo (Khoảng -10 tỷ đến -10.000 năm)&quot;">​</a></h2><p>Thời đại tiền-mỏ neo là kỷ nguyên dài nhất trong lịch sử Hengyuanzhou, kéo dài khoảng mười tỷ năm. Đặc điểm cốt lõi của thời đại này là hệ thống tu luyện kiểu cướp bóc chiếm ưu thế trong vũ trụ, và các văn minh liên tục luân chuyển trong chu kỳ &quot;trỗi dậy—đỉnh cao—cướp bóc—sụp đổ&quot;.</p><table tabindex="0"><thead><tr><th>Nút thời gian</th><th>Sự kiện quan trọng</th></tr></thead><tbody><tr><td>Khoảng -10 tỷ năm</td><td>Mạng lưới quy luật của Hengyuanzhou ổn định, các mặt phẳng vật chất đầu tiên được hình thành, vũ trụ đi vào trạng thái có thể sinh sống</td></tr><tr><td>Khoảng -8 tỷ năm</td><td>Sự sống thông minh đầu tiên ra đời ở nhiều mặt phẳng vật chất, hệ thống tu luyện nguyên thủy bắt đầu nảy mầm</td></tr><tr><td>Khoảng -5 tỷ năm</td><td>Hệ thống tu luyện kiểu cướp bóc dần dần trở thành xu hướng chính, người mạnh tiến hóa nhanh chóng bằng cách nuốt chửng người yếu</td></tr><tr><td>Khoảng -3 tỷ năm</td><td>Cuộc chiến cướp bóc cấp vũ trụ đầu tiên bùng nổ, các văn minh ở nhiều miền sao chịu đòn đánh phá hủy</td></tr><tr><td>Khoảng -1 tỷ năm</td><td>Nhược điểm của hệ thống kiểu cướp bóc bắt đầu xuất hiện, entropy tổng thể của vũ trụ tăng nhanh, tài nguyên tu luyện ngày càng cạn kiệt</td></tr><tr><td>Khoảng -500 triệu năm</td><td>Những nhà tư tưởng đầu tiên phản ánh hệ thống kiểu cướp bóc xuất hiện, mầm mống tư tưởng cộng sinh bắt đầu được nuôi dưỡng</td></tr><tr><td>Khoảng -100 triệu năm</td><td>Các văn minh thử nghiệm cộng sinh quy mô nhỏ xuất hiện ở nhiều miền sao, nhưng tất cả đều bị văn minh kiểu cướp bóc phá hủy</td></tr><tr><td>Khoảng -1 triệu năm</td><td>Vũ trụ nói chung đi vào &quot;giai đoạn suy thoái lớn&quot;, cả số lượng văn minh và mức độ tu luyện đều giảm xuống mức thấp nhất lịch sử</td></tr><tr><td>Khoảng -10.000 năm</td><td>Một người tu luyện từ mặt phẳng đầu tiên tình cờ cảm nhận được các nút ổn định trong mạng lưới quy luật trong quá trình tu luyện dài hạn, cơ chế mỏ neo được phát hiện lần đầu tiên</td></tr></tbody></table><h2 id="_4-ky-nguyen-thuc-tinh-mo-neo-10-000-đen-1-000-nam" tabindex="-1">4. Kỷ nguyên thức tỉnh mỏ neo (-10.000 đến -1.000 năm) <a class="header-anchor" href="#_4-ky-nguyen-thuc-tinh-mo-neo-10-000-đen-1-000-nam" aria-label="Permalink to &quot;4. Kỷ nguyên thức tỉnh mỏ neo (-10.000 đến -1.000 năm)&quot;">​</a></h2><p>Kỷ nguyên thức tỉnh mỏ neo là giai đoạn chuyển tiếp từ phát hiện đến áp dụng ban đầu của cơ chế mỏ neo. Đặc điểm cốt lõi của kỷ nguyên này là sự trưởng thành dần dần của công nghệ mỏ neo và sự lan tỏa của tư tưởng cộng sinh.</p><table tabindex="0"><thead><tr><th>Nút thời gian</th><th>Sự kiện quan trọng</th></tr></thead><tbody><tr><td>-10.000 năm</td><td>Cơ chế mỏ neo được phát hiện lần đầu tiên, người phát hiện đặt tên cho nó là &quot;mỏ neo&quot;, và bắt đầu nghiên cứu có hệ thống</td></tr><tr><td>-9.000 năm</td><td>Mỏ neo nhân tạo đầu tiên được xây dựng thành công, chứng minh rằng mỏ neo có thể được xây dựng và duy trì một cách nhân tạo</td></tr><tr><td>-8.000 năm</td><td>Công nghệ mỏ neo bắt đầu lan tỏa trong quy mô nhỏ, những người tu luyện mỏ neo đầu tiên xuất hiện</td></tr><tr><td>-7.000 năm</td><td>Phát hiện ra rằng mỏ neo có thể làm cơ sở cho kết nối liên mặt phẳng, chuyến du hành liên mặt phẳng hỗ trợ bởi mỏ neo đầu tiên được ghi nhận thành công</td></tr><tr><td>-6.000 năm</td><td>Tư tưởng cộng sinh và công nghệ mỏ neo bắt đầu kết hợp, những tài liệu lý luận &quot;cộng sinh mỏ neo&quot; đầu tiên được xuất bản</td></tr><tr><td>-5.000 năm</td><td>Thành phố-quốc gia kiểu cộng sinh đầu tiên dựa trên mỏ neo được thành lập, chứng minh tính khả thi của hệ thống cộng sinh</td></tr><tr><td>-4.000 năm</td><td>Văn minh kiểu cướp bóc phát động tấn công chống lại thành phố-quốc gia kiểu cộng sinh, thành phố-quốc gia cộng sinh phòng thủ thành công thông qua công nghệ mỏ neo</td></tr><tr><td>-3.000 năm</td><td>Tư tưởng cộng sinh lan tỏa ở nhiều miền sao, ngày càng nhiều văn minh bắt đầu thử nghiệm chuyển đổi cộng sinh</td></tr><tr><td>-2.000 năm</td><td>&quot;Hội nghị Cộng sinh Tất cả các Chủng tộc&quot; đầu tiên được tổ chức, đại diện của hàng chục chủng tộc cùng thảo luận về tương lai của văn minh cộng sinh</td></tr><tr><td>-1.000 năm</td><td>Công nghệ mỏ neo và tư tưởng cộng sinh đã đáp ứng các điều kiện để thành lập văn minh thống nhất, giai đoạn thành lập hệ thống cộng sinh bắt đầu</td></tr></tbody></table><h2 id="_5-giai-đoan-thanh-lap-he-thong-cong-sinh-1-000-đen-100-nam" tabindex="-1">5. Giai đoạn thành lập hệ thống cộng sinh (-1.000 đến -100 năm) <a class="header-anchor" href="#_5-giai-đoan-thanh-lap-he-thong-cong-sinh-1-000-đen-100-nam" aria-label="Permalink to &quot;5. Giai đoạn thành lập hệ thống cộng sinh (-1.000 đến -100 năm)&quot;">​</a></h2><p>Giai đoạn thành lập hệ thống cộng sinh là giai đoạn then chốt mà khung thể chế của Văn minh Cộng sinh Mỏ neo hình thành từ không có đến có.</p><table tabindex="0"><thead><tr><th>Nút thời gian</th><th>Sự kiện quan trọng</th></tr></thead><tbody><tr><td>-1.000 năm</td><td>Ủy ban soạn thảo Hiến pháp Cộng sinh được thành lập, bắt đầu soạn thảo luật cơ bản</td></tr><tr><td>-950 năm</td><td>Dự thảo &quot;Hiến pháp Cộng sinh&quot; hoàn thành, bắt đầu xin ý kiến rộng rãi từ tất cả các chủng tộc</td></tr><tr><td>-900 năm</td><td>&quot;Hiến pháp Cộng sinh&quot; được thông qua thông qua trưng cầu dân ý toàn dân, chính thức có hiệu lực, Văn minh Cộng sinh Mỏ neo được tuyên bố thành lập</td></tr><tr><td>-850 năm</td><td>Hội đồng Mỏ neo, Ủy ban Hành chính Cộng sinh, Tòa án Cộng sinh ba cơ quan chính thức được thành lập và vận hành</td></tr><tr><td>-800 năm</td><td>Cơ chế hợp đồng sản xuất chung bắt đầu được triển khai trên toàn quốc</td></tr><tr><td>-700 năm</td><td>&quot;Luật Lao động Cộng sinh&quot;, &quot;Luật Bảo vệ Người tiêu dùng&quot; và các luật cơ bản khác được ban hành liên tiếp</td></tr><tr><td>-600 năm</td><td>Năm luật hỗ trợ về giáo dục, y tế, nhà ở, môi trường, và chống độc quyền tất cả được ban hành và thực thi</td></tr><tr><td>-500 năm</td><td>Công việc khai quật và sắp xếp hệ thống tu luyện nguồn gốc ba trăm bộ chính thức được khởi động</td></tr><tr><td>-400 năm</td><td>Năm mươi bộ hệ thống tu luyện nguồn gốc đầu tiên hoàn thành sắp xếp và xác minh</td></tr><tr><td>-300 năm</td><td>Ứng dụng công nghệ của trái nhân đôi đạt được đột phá, công nghệ khuếch đại suy luận trăm lần trưởng thành</td></tr><tr><td>-200 năm</td><td>Tất cả ba trăm bộ hệ thống hoàn thành sắp xếp, đi vào giai đoạn xác minh an toàn cuối cùng</td></tr><tr><td>-100 năm</td><td>Điều kiện mở cửa hoàn toàn của hệ thống tu luyện nguồn gốc ba trăm bộ trưởng thành, đi vào giai đoạn mở cửa</td></tr></tbody></table><h2 id="_6-giai-đoan-mo-cua-he-thong-ba-tram-bo-100-đen-50-nam" tabindex="-1">6. Giai đoạn mở cửa hệ thống ba trăm bộ (-100 đến -50 năm) <a class="header-anchor" href="#_6-giai-đoan-mo-cua-he-thong-ba-tram-bo-100-đen-50-nam" aria-label="Permalink to &quot;6. Giai đoạn mở cửa hệ thống ba trăm bộ (-100 đến -50 năm)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nút thời gian</th><th>Sự kiện quan trọng</th></tr></thead><tbody><tr><td>-100 năm</td><td>Hệ thống tu luyện nguồn gốc ba trăm bộ chính thức được mở cửa miễn phí cho tất cả chúng sinh trong vũ trụ</td></tr><tr><td>-90 năm</td><td>Số lượng người tu luyện tăng trăm lần trong mười năm, &quot;mọi người đều có con đường&quot; ban đầu được thực hiện</td></tr><tr><td>-80 năm</td><td>Ba nền tảng nguồn gốc (lặp lại suy luận, chu kỳ sống, điều phối quy luật không gian) trở thành hệ thống phổ biến nhất</td></tr><tr><td>-70 năm</td><td>Những người tu luyện đầu tiên đạt cấp cao thông qua hệ thống mới xuất hiện, chứng minh hiệu quả của hệ thống</td></tr><tr><td>-60 năm</td><td>Mạng lưới cố vấn hoàn toàn được xây dựng, người tu luyện cấp cao bắt đầu thực hiện nghĩa vụ pháp lý hướng dẫn người tu luyện cấp dưới</td></tr><tr><td>-50 năm</td><td>Mức độ tu luyện của toàn dân tăng đáng kể, điều kiện cho chiến lược kích hoạt 20% trưởng thành</td></tr></tbody></table><h2 id="_7-giai-đoan-chien-luoc-kich-hoat-20-50-nam-đen-nam-goc" tabindex="-1">7. Giai đoạn chiến lược kích hoạt 20% (-50 năm đến năm gốc) <a class="header-anchor" href="#_7-giai-đoan-chien-luoc-kich-hoat-20-50-nam-đen-nam-goc" aria-label="Permalink to &quot;7. Giai đoạn chiến lược kích hoạt 20% (-50 năm đến năm gốc)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nút thời gian</th><th>Sự kiện quan trọng</th></tr></thead><tbody><tr><td>-50 năm</td><td>Chiến lược kích hoạt 20% chính thức được khởi động, mục tiêu là trong 50 năm kích hoạt 20% chúng sinh trở thành người mạnh nhất cấp mặt phẳng</td></tr><tr><td>-40 năm</td><td>Những người mạnh nhất cấp mặt phẳng đầu tiên ra đời, tỷ lệ kích hoạt đạt 5%</td></tr><tr><td>-30 năm</td><td>Tỷ lệ kích hoạt đạt 10%, người mạnh nhất cấp mặt phẳng bắt đầu đóng vai trò cốt lõi trong việc duy trì mỏ neo</td></tr><tr><td>-20 năm</td><td>Tỷ lệ kích hoạt đạt 15%, mức độ tu luyện tổng thể của vũ trụ đạt được bước nhảy vọt về chất</td></tr><tr><td>-10 năm</td><td>Tỷ lệ kích hoạt đạt 18%, gần với mục tiêu chiến lược</td></tr><tr><td>Năm gốc</td><td>Tỷ lệ kích hoạt đạt 20,3%, chiến lược kích hoạt 20% hoàn thành thành công, Văn minh Cộng sinh Mỏ neo đi vào kỷ nguyên mới</td></tr></tbody></table><h2 id="_8-ky-nguyen-nang-chieu-khong-gian-đau-tien-nam-goc-đen-100-nam" tabindex="-1">8. Kỷ nguyên nâng chiều không gian đầu tiên (Năm gốc đến 100 năm) <a class="header-anchor" href="#_8-ky-nguyen-nang-chieu-khong-gian-đau-tien-nam-goc-đen-100-nam" aria-label="Permalink to &quot;8. Kỷ nguyên nâng chiều không gian đầu tiên (Năm gốc đến 100 năm)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nút thời gian</th><th>Sự kiện quan trọng</th></tr></thead><tbody><tr><td>Năm gốc</td><td>Văn minh cộng sinh chính thức tuyên bố đi vào kỷ nguyên nâng chiều không gian, giai đoạn đầu tiên của con đường nâng chiều không gian bốn giai đoạn (nền tảng thực tế) hoàn thành</td></tr><tr><td>20 năm</td><td>Giai đoạn thứ hai (trao quyền công nghệ) được tiến hành toàn diện, quy luật tu luyện và kỹ thuật công nghệ được tích hợp sâu sắc</td></tr><tr><td>40 năm</td><td>Công nghệ gương sao chép, công nghệ không gian cách ly đạt được sản xuất hàng loạt kỹ thuật, khảo cổ liên mặt phẳng đi vào thời đại quy mô</td></tr><tr><td>60 năm</td><td>Những người tu luyện lớp nâng chiều không gian ý thức đầu tiên đạt cấp cao, giai đoạn thứ ba (tiến hóa ý thức) bắt đầu</td></tr><tr><td>80 năm</td><td>Xây dựng cơ sở hạ tầng của miền ý thức hoàn thành, công nghệ di chuyển ý thức ban đầu trưởng thành</td></tr><tr><td>100 năm</td><td>Nâng chiều không gian theo giai đoạn đầu tiên thành công, văn minh cộng sinh nói chung nâng lên nửa cấp độ chiều không gian</td></tr></tbody></table><h2 id="_9-ky-nguyen-cong-hoa-tat-ca-cac-chung-toc-100-đen-500-nam" tabindex="-1">9. Kỷ nguyên cộng hòa tất cả các chủng tộc (100 đến 500 năm) <a class="header-anchor" href="#_9-ky-nguyen-cong-hoa-tat-ca-cac-chung-toc-100-đen-500-nam" aria-label="Permalink to &quot;9. Kỷ nguyên cộng hòa tất cả các chủng tộc (100 đến 500 năm)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nút thời gian</th><th>Sự kiện quan trọng</th></tr></thead><tbody><tr><td>100 năm</td><td>Cộng hòa tất cả các chủng tộc chính thức tuyên bố thành lập, tất cả các chủng tộc thông minh đạt được liên minh bình đẳng trong khuôn khổ văn minh cộng sinh</td></tr><tr><td>150 năm</td><td>Biên soạn danh mục tất cả các chủng tộc hoàn thành, bao gồm tất cả các chủng tộc thông minh đã biết</td></tr><tr><td>200 năm</td><td>Hôn nhân liên chủng tộc và hòa nhập văn hóa trở thành bình thường, các chủng tộc hỗn hợp mới bắt đầu xuất hiện</td></tr><tr><td>300 năm</td><td>Phổ biến ngôn ngữ chung của tất cả các chủng tộc hoàn thành, rào cản giao tiếp liên chủng tộc cơ bản được loại bỏ</td></tr><tr><td>400 năm</td><td>Văn hóa tất cả các chủng tộc phát triển mạnh mẽ, văn hóa truyền thống của mỗi dân tộc được bảo vệ và phát triển trong khuôn khổ cộng sinh</td></tr><tr><td>500 năm</td><td>Cộng hòa tất cả các chủng tộc đi vào giai đoạn trưởng thành, điều kiện cho khám phá liên mặt phẳng hoàn toàn trưởng thành</td></tr></tbody></table><h2 id="_10-ky-nguyen-kham-pha-lien-mat-phang-500-đen-2-000-nam" tabindex="-1">10. Kỷ nguyên khám phá liên mặt phẳng (500 đến 2.000 năm) <a class="header-anchor" href="#_10-ky-nguyen-kham-pha-lien-mat-phang-500-đen-2-000-nam" aria-label="Permalink to &quot;10. Kỷ nguyên khám phá liên mặt phẳng (500 đến 2.000 năm)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nút thời gian</th><th>Sự kiện quan trọng</th></tr></thead><tbody><tr><td>500 năm</td><td>Kế hoạch khám phá liên mặt phẳng quy mô lớn chính thức được khởi động, cục quản lý mặt phẳng được thành lập</td></tr><tr><td>600 năm</td><td>Các mặt phẳng đã được khám phá vượt quá một nghìn, kho tọa độ mặt phẳng chung ban đầu được xây dựng</td></tr><tr><td>800 năm</td><td>Kế hoạch khảo cổ từ xa bằng gương sao chép hoàn toàn trưởng thành, khảo cổ liên mặt phẳng đi vào thời đại vàng</td></tr><tr><td>1.000 năm</td><td>Công nghệ hồi quy thời gian đạt được đột phá, nguyên tắc quan sát trước, sau đó can thiệp hạn chế chính thức được thiết lập</td></tr><tr><td>1.200 năm</td><td>Các mặt phẳng đã được khám phá vượt quá một trăm nghìn, quan hệ ngoại giao được thiết lập với hàng chục văn minh mặt phẳng</td></tr><tr><td>1.500 năm</td><td>Nguyên tắc đạo đức liên mặt phẳng được thực thi toàn diện, tương tác giữa các văn minh đi vào thời đại chuẩn hóa</td></tr><tr><td>1.800 năm</td><td>Cơ chế phòng ngừa nghịch lý thời gian hoàn toàn trưởng thành, khảo cổ hồi quy thời gian đạt được quy mô</td></tr><tr><td>2.000 năm</td><td>Khám phá liên mặt phẳng đạt được kết quả rực rỡ, điều kiện cho thời đại cộng sinh liên sao hoàn toàn trưởng thành</td></tr></tbody></table><h2 id="_11-thoi-đai-cong-sinh-lien-sao-2-000-nam-đen-tuong-lai" tabindex="-1">11. Thời đại cộng sinh liên sao (2.000 năm đến tương lai) <a class="header-anchor" href="#_11-thoi-đai-cong-sinh-lien-sao-2-000-nam-đen-tuong-lai" aria-label="Permalink to &quot;11. Thời đại cộng sinh liên sao (2.000 năm đến tương lai)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nút thời gian</th><th>Sự kiện quan trọng</th></tr></thead><tbody><tr><td>2.000 năm</td><td>Thời đại cộng sinh liên sao chính thức được khai mở, giai đoạn thứ tư (cộng sinh liên sao) được tiến hành toàn diện</td></tr><tr><td>2.500 năm (triển vọng)</td><td>Mạng lưới mỏ neo cấp vũ trụ ban đầu được xây dựng, bao phủ tất cả các mặt phẳng đã được khám phá</td></tr><tr><td>3.000 năm (triển vọng)</td><td>Hệ thống cộng sinh liên mặt phẳng trưởng thành, tất cả các chủng tộc đạt được cộng sinh thực sự trong quy mô vũ trụ</td></tr><tr><td>5.000 năm (triển vọng)</td><td>Nâng chiều không gian tổng thể của vũ trụ hoàn thành, Hengyuanzhou đi vào trạng thái tồn tại chiều không gian cao hơn</td></tr><tr><td>Tương lai (triển vọng)</td><td>Văn minh Cộng sinh Mỏ neo tiếp tục khám phá ra ngoài vũ trụ, lan tỏa tư tưởng cộng sinh đến sự tồn tại rộng lớn hơn</td></tr></tbody></table><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Bảng tóm tắt biên niên sử là sử thi đấu tranh của Văn minh Cộng sinh Mỏ neo, từ mê mẩn đến thức tỉnh, từ yếu đuối đến mạnh mẽ, từ mặt phẳng riêng đến toàn bộ vũ trụ. Mỗi sự thay thế của kỷ nguyên là nhân chứng cho chiến thắng của tư tưởng cộng sinh trước tư tưởng cướp bóc, tiến bộ văn minh trước suy thoái man rợ. Lịch sử không phải là bụi của quá khứ, mà là hạt giống của tương lai—hiểu được lịch sử này chính là hiểu được văn minh cộng sinh đến từ đâu và đi về đâu.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu Liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu Liên quan&quot;">​</a></h2><ul><li>70-Bảng Tổng quan Phân chia Kỷ nguyên</li><li>72-Kỷ nguyên thức tỉnh mỏ neo</li><li>79-Triển vọng Thời đại Cộng sinh Liên sao</li></ul>',32)])])}const b=t(g,[["render",a]]);export{e as __pageData,b as default};
